/**
 * The app's Modal and confirmation dialog (src/ui/Modal.tsx, src/ui/IconButton.tsx,
 * src/ui/ConfirmDialog.tsx) as static scene markup. The app portals a dialog
 * to <body>; a scene renders it inside the app window instead: the window's
 * backdrop-filter makes it the containing block of the fixed backdrop, so the
 * dialog centres on the window as it does in the app.
 */
import type { CSSProperties, ReactNode } from "react";
import { X, type LucideIcon } from "lucide-react";

/** What the app's useModalFocus puts on the backdrop: 400 + the layer count, 1000 + it for a confirmation. */
const LAYER = { dialog: 401, alertdialog: 1001 } as const;

export function Modal({
  title,
  icon: Icon,
  size = "md",
  role = "dialog",
  className = "",
  children,
}: {
  title: string;
  icon?: LucideIcon;
  size?: "sm" | "md" | "lg" | "xl";
  role?: "dialog" | "alertdialog";
  className?: string;
  children: ReactNode;
}) {
  return (
    <div className={`modal-backdrop pzza-portal ${role === "alertdialog" ? "confirmation-backdrop" : ""}`} style={{ zIndex: LAYER[role] }}>
      <div className={`modal modal-${size} ${className}`} tabIndex={-1} role={role} aria-modal="true" aria-label={title}>
        <div className="modal-head">
          <span className="modal-title">
            {Icon ? <Icon size={15} className="modal-title-icon" /> : null}
            {title}
          </span>
          <button type="button" className="icon-btn" title="Close" aria-label="Close">
            <span className="icon-inner">
              <X size={15} strokeWidth={1.9} />
            </span>
          </button>
        </div>
        <div className="modal-body">{children}</div>
      </div>
    </div>
  );
}

/** A confirmation (confirmAction in src/state/confirmations.ts) as the app's ConfirmationHost shows it. */
export function Confirmation({ title, message, confirmLabel = "Confirm", danger = false }: { title: string; message: string; confirmLabel?: string; danger?: boolean }) {
  return (
    <Modal title={title} role="alertdialog" size="sm">
      <p className="confirmation-message">{message}</p>
      <div className="modal-actions">
        <button type="button" className="btn">
          Cancel
        </button>
        <button type="button" className={`btn ${danger ? "btn-danger" : "btn-accent"}`}>
          {confirmLabel}
        </button>
      </div>
    </Modal>
  );
}

/**
 * The viewport the app's dialogs size against (vh / vw in its stylesheet read
 * --pz-vh / --pz-vw in app.css): the scene window's own size, set on the window.
 */
export function windowViewport(width: number, height: number): CSSProperties {
  return { "--pz-vh": `${height / 100}px`, "--pz-vw": `${width / 100}px` } as CSSProperties;
}
